long long coinChange(std::vector<long long> coins, long long amount) {
    const long long INF = (long long)1e18;
    std::vector<long long> best((std::size_t)amount + 1, INF);
    best[0] = 0;
    for (long long value = 1; value <= amount; ++value) {
        for (std::size_t i = 0; i < coins.size(); ++i) {
            long long coin = coins[i];
            if (coin <= value && best[(std::size_t)(value - coin)] != INF &&
                best[(std::size_t)(value - coin)] + 1 < best[(std::size_t)value]) {
                best[(std::size_t)value] = best[(std::size_t)(value - coin)] + 1;
            }
        }
    }
    return best[(std::size_t)amount] == INF ? -1 : best[(std::size_t)amount];
}
